/// A member of an [`OShape`] structure / union.
pub struct OMember {
    pub wire: &'static str,
    /// The member's shape: an index into [`OSHAPES`].
    pub shape: u16,
    pub req: bool,
}

/// A node of an operation output's full shape tree. Structures / unions
/// list their members; lists and maps point `elem` at their element / value
/// node; scalars carry the constraints a synthesised value must honour
/// (`min_len` is a list's `@length` min on a list node).
pub struct OShape {
    pub kind: K,
    pub union: bool,
    pub members: &'static [OMember],
    pub elem: u16,
    pub enums: &'static [&'static str],
    /// The modelled values of an `intEnum` leaf.
    pub int_enums: &'static [i64],
    pub min_len: Option<u64>,
    pub min_val: Option<i64>,
}

